const orders=[
  {time:'2026-08-19 10:31:18',province:'北京',order:'BIZ202608190001',no:'P20260819000001',channel:'微信支付',amount:1999,status:'PAID',merchant:'北京联通营业厅',refund:0},
  {time:'2026-08-18 15:22:09',province:'北京',order:'BIZ202608180032',no:'P20260818000032',channel:'支付宝',amount:9900,status:'PAID',merchant:'北京联通营业厅',refund:0},
  {time:'2026-08-18 09:08:51',province:'上海',order:'BIZ202608180118',no:'P20260818000118',channel:'沃支付',amount:5000,status:'REFUNDED',merchant:'上海联通营业厅',refund:5000},
  {time:'2026-08-17 18:38:42',province:'北京',order:'BIZ202608170201',no:'P20260817000201',channel:'微信支付',amount:2000,status:'PAID',merchant:'北京联通营业厅',refund:0}
];
let selected='WOPAY';
const $=s=>document.querySelector(s), money=f=>'¥'+(f/100).toFixed(2), statusName=s=>s==='PAID'?'成功':s==='REFUNDED'?'已退款':'部分退款';
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function renderOrders(){const filter=$('#statusFilter')?.value||'ALL';const list=orders.filter(o=>filter==='ALL'||o.status===filter);$('#transactionRows').innerHTML=list.map(o=>`<tr><td>${o.time}</td><td>${o.province}</td><td>${o.order}</td><td>${o.no}</td><td>${o.channel}</td><td>${money(o.amount)}</td><td><span class="tag ${o.status==='REFUNDED'?'warning':''}">${statusName(o.status)}</span></td><td>${o.merchant}</td><td>${o.status==='PAID'?`<button class="link refund" data-no="${o.no}">退款</button>　<button class="link revoke" data-no="${o.no}">撤销</button>`:'-'}</td></tr>`).join('');$('#recordCount').textContent=`共 ${list.length} 条`;$('#merchantRows').innerHTML=orders.filter(o=>o.merchant==='北京联通营业厅').map(o=>`<tr><td>${o.time}</td><td>${o.order}</td><td>${o.no}</td><td>${o.channel}</td><td>${money(o.amount)}</td><td><span class="tag ${o.status==='REFUNDED'?'warning':''}">${statusName(o.status)}</span></td><td>${money(o.refund)}</td></tr>`).join('');bindActions()}
function renderReport(){const data=[['2026-08-15','北京','微信支付','成功','2,428','¥75,382.00'],['2026-08-16','北京','支付宝','成功','2,186','¥68,942.25'],['2026-08-17','上海','沃支付','成功','1,944','¥52,918.00'],['2026-08-18','北京','微信支付','成功','3,102','¥98,231.00'],['2026-08-19','北京','支付宝','成功','2,826','¥91,447.00']];$('#summaryRows').innerHTML=data.map(x=>'<tr>'+x.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('');$('#bars').innerHTML=[70,56,43,90,78].map(h=>`<i style="height:${h}%"></i>`).join('')}
function bindActions(){document.querySelectorAll('.refund').forEach(b=>b.onclick=()=>openRefund(b.dataset.no));document.querySelectorAll('.revoke').forEach(b=>b.onclick=()=>{const o=orders.find(x=>x.no===b.dataset.no);o.status='REFUNDED';o.refund=o.amount;renderOrders();toast('已模拟完成当日全额撤销，状态已同步更新')})}
function openRefund(no){const o=orders.find(x=>x.no===no);$('#modalContent').innerHTML=`<h3>发起退款</h3><p>支付单号：${no}<br>可退金额：${money(o.amount-o.refund)}</p><label>退款金额（元）</label><input id="refundAmount" value="${((o.amount-o.refund)/100).toFixed(2)}"><label>退款原因</label><input value="用户申请退款"><p style="text-align:right;margin-top:20px"><button class="plain close">取消</button><button class="primary" id="confirmRefund">确认退款</button></p>`;$('#modal').classList.add('open');$('#confirmRefund').onclick=()=>{const v=Math.round(parseFloat($('#refundAmount').value)*100);if(!v||v>o.amount-o.refund)return toast('退款金额必须大于 0 且不超过可退金额');o.refund+=v;o.status=o.refund===o.amount?'REFUNDED':'PARTIALLY_REFUNDED';$('#modal').classList.remove('open');renderOrders();toast('退款申请已受理，模拟通道返回成功')}}
function activateView(view){const button=document.querySelector(`.nav[data-view="${view}"]`);if(!button)return;document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.querySelectorAll('.view').forEach(x=>x.classList.remove('visible'));$('#'+view).classList.add('visible');$('#crumb').textContent=button.textContent}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>activateView(b.dataset.view));
document.querySelectorAll('.channel').forEach(b=>b.onclick=()=>{document.querySelectorAll('.channel').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selected=b.dataset.channel;$('#payButton').textContent='确认使用 '+b.querySelector('span').textContent+' 支付 ¥19.99'});
$('#payButton').onclick=()=>{const channel={WOPAY:'沃支付',WECHAT:'微信支付',ALIPAY:'支付宝'}[selected];orders[0].channel=channel;orders[0].time='2026-08-19 10:31:18';renderOrders();toast(channel+' 支付成功：已完成回调与商户通知（模拟）')};
$('#searchButton').onclick=()=>{renderOrders();toast('已按条件刷新交易明细')};$('#merchantSearch').onclick=()=>toast('已按商户数据权限刷新');$('#reportSearch').onclick=()=>toast($('#granularity').value==='month'?'已切换为月报统计':'已刷新日报统计');$('#granularity').onchange=e=>{const isMonth=e.target.value==='month';$('#reportStart').type=$('#reportEnd').type=isMonth?'month':'date'};
document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>toast('已生成 Excel 导出任务（原型模拟）'));document.querySelectorAll('.resolve').forEach(b=>b.onclick=()=>{b.parentElement.previousElementSibling.innerHTML='<span class="tag">处理中</span>';toast('异常差异已转入人工复核队列')});$('#modal').onclick=e=>{if(e.target.id==='modal'||e.target.classList.contains('close'))$('#modal').classList.remove('open')};
renderOrders();renderReport();activateView(new URLSearchParams(location.search).get('view')||'checkout');
